+/**
+ * Resolves the Coinbase Exchange REST and WebSocket hosts.
+ * Set COINBASE_MICA=true for MiCA-regulated Exchange customers.
+ * COINBASE_API_URI / COINBASE_WS_URI override everything.
+ */
+const HOSTS = {
+    standard: {
+        real: { api: "https://api.exchange.coinbase.com", ws: "wss://ws-feed.exchange.coinbase.com" },
+        sandbox: { api: "https://api-public.sandbox.exchange.coinbase.com", ws: "wss://ws-feed-public.sandbox.exchange.coinbase.com" }
+    },
+    mica: {
+        real: { api: "https://api-us.dma.prime.coinbase.com", ws: "wss://ws-us.dma.prime.coinbase.com" },
+        sandbox: { api: "https://api-us.dma.sandbox.prime.coinbase.com", ws: "wss://ws-us.dma.sandbox.prime.coinbase.com" }
+    }
+};
+
+function getHosts(env = process.env) {
+    const region = String(env.COINBASE_MICA).toLowerCase() === "true" ? "mica" : "standard";
+    const mode = env.TRADING_ENV === "real" ? "real" : "sandbox";
+    return {
+        apiURI: env.COINBASE_API_URI || HOSTS[region][mode].api,
+        websocketURI: env.COINBASE_WS_URI || HOSTS[region][mode].ws
+    };
+}
+
+module.exports = { getHosts };
